select jsonb_build_object('roles',(select jsonb_agg(x) from (select r.role_key,r.display_name,count(*) organizations from organization_role_types r join organizations o on o.id=r.organization_id where o.business_type='school' and r.role_key ilike '%burs%' group by 1,2) x),'overrides',(select jsonb_agg(x) from (select s.role,p.permission_key,p.allowed,count(*) from staff_permission_overrides p join staff s on s.id=p.staff_id join organizations o on o.id=p.organization_id where o.business_type='school' and s.role ilike '%burs%' and p.permission_key like '%payroll%' group by 1,2,3) x),'grants',(select jsonb_agg(x) from (select p.role_key,p.permission_key,p.allowed,count(*) from organization_permissions p join organizations o on o.id=p.organization_id where o.business_type='school' and p.role_key ilike '%burs%' and p.permission_key like '%payroll%' group by 1,2,3) x));
